-- Broaden P1 Challenge Me coverage across seeded role families.
-- Each newly covered core skill has four validated items so it can be selected by the adaptive assessment service.

insert into public.assessment_question_bank(
  id,skill_id,concept_id,type,difficulty,prompt,options,answer_key,rubric,tags,source,version,is_active
) values

-- Python
('72000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','collections','MCQ',1,
'Which Python built-in collection stores unique values and supports fast membership checks?',
'[{"id":"a","text":"list"},{"id":"b","text":"set"},{"id":"c","text":"tuple"},{"id":"d","text":"str"}]'::jsonb,
'{"correctOptionId":"b"}'::jsonb,
'{"correctFeedback":"A set stores unique values and is designed for efficient membership checks.","incorrectFeedback":"Choose the collection whose elements are unique and hash-based."}'::jsonb,
'["python","collections","set"]'::jsonb,'SEEDED','role-bank-h1',true),
('72000000-0000-0000-0000-000000000002','10000000-0000-0000-0000-000000000001','exceptions','MCQ',2,
'What is the primary purpose of a try/except block in Python?',
'[{"id":"a","text":"To define a class"},{"id":"b","text":"To handle exceptions without unconditionally terminating the program"},{"id":"c","text":"To import packages"},{"id":"d","text":"To make every function asynchronous"}]'::jsonb,
'{"correctOptionId":"b"}'::jsonb,
'{"correctFeedback":"try/except lets code handle specified exceptions deliberately.","incorrectFeedback":"Think about controlled handling of runtime errors."}'::jsonb,
'["python","exceptions"]'::jsonb,'SEEDED','role-bank-h1',true),
('72000000-0000-0000-0000-000000000003','10000000-0000-0000-0000-000000000001','comprehensions','MCQ',2,
'What does the expression [x * 2 for x in values if x > 0] produce?',
'[{"id":"a","text":"A new list containing doubled positive values"},{"id":"b","text":"A set of all values"},{"id":"c","text":"A generator that can be used only once"},{"id":"d","text":"A dictionary keyed by x"}]'::jsonb,
'{"correctOptionId":"a"}'::jsonb,
'{"correctFeedback":"The list comprehension filters positive values and transforms each one.","incorrectFeedback":"Read the expression as filter first, then transform into a list."}'::jsonb,
'["python","comprehension"]'::jsonb,'SEEDED','role-bank-h1',true),
('72000000-0000-0000-0000-000000000004','10000000-0000-0000-0000-000000000001','mutability','SHORT_TEXT',3,
'Why can using a mutable object such as a list as a default function argument cause surprising behavior in Python?',
null,
'{"referenceAnswer":"Default argument objects are created once when the function is defined, so mutations can persist across later calls that reuse the same default object.","expectedKeywords":["default","once","mutation","calls"]}'::jsonb,
'{"criteria":[{"id":"lifetime","weight":0.5,"description":"Explains the default object is created once rather than per call"},{"id":"mutation","weight":0.5,"description":"Explains mutations can persist across calls"}],"maxScore":1}'::jsonb,
'["python","functions","mutability"]'::jsonb,'SEEDED','role-bank-h1',true),

