'{"criteria":[{"id":"repetition","weight":0.55,"description":"Explains repeated-sampling coverage"},{"id":"parameter","weight":0.45,"description":"Distinguishes procedure coverage from a posterior probability about a fixed parameter"}],"maxScore":1}'::jsonb,
