('72000000-0000-0000-0000-000000000044','10000000-0000-0000-0000-000000000031','strategy-tradeoff','SCENARIO',3,
'Usage is growing, but retention is falling after the first week. The team proposes adding more acquisition campaigns. What would you investigate before committing to that strategy?',
null,
'{"referenceAnswer":"Investigate where and why users fail to receive recurring value, segment retention/cohorts, validate the activation and retention problem, and avoid scaling acquisition before understanding the retention leak.","expectedKeywords":["retention","cohort","value","acquisition"]}'::jsonb,
'{"criteria":[{"id":"diagnose","weight":0.55,"description":"Prioritizes diagnosing retention and recurring value before scaling acquisition"},{"id":"evidence","weight":0.45,"description":"Uses cohorts/segments or other evidence to localize the problem"}],"maxScore":1}'::jsonb,
'["product-strategy","retention","tradeoffs"]'::jsonb,'SEEDED','role-bank-h1',true)

on conflict(id) do update set
  skill_id=excluded.skill_id,
  concept_id=excluded.concept_id,
  type=excluded.type,
  difficulty=excluded.difficulty,
  prompt=excluded.prompt,
  options=excluded.options,
  answer_key=excluded.answer_key,
  rubric=excluded.rubric,
  tags=excluded.tags,
  source=excluded.source,
  version=excluded.version,
  is_active=true;
